# -*- coding: utf-8 -*-
"""Оферта и политика конфиденциальности. Реквизиты — tools/req.json. После запуска: python3 tools/seo.py"""
import os, json
# реквизиты: из req.json (заполняется по старой политике), иначе — пометки для заполнения
REQ = {'name': 'ТОО «[наименование]»', 'bin': '[БИН]', 'addr': '[юридический адрес]', 'bank': ['Банковские реквизиты: [—]'], 'date': '[дата]'}
_rq = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'req.json')  # реквизиты: tools/req.json {name,bin,addr,bank:[…],date}
if os.path.exists(_rq): REQ.update(json.load(open(_rq)))
src=open(os.path.join(os.path.dirname(os.path.abspath(__file__)),'gen_pages.py'),encoding='utf-8').read()
exec(src[:src.index("for fn,kind,title in")])   # head(), FOOT
exec(src[src.index("def doc("):src.index("doc('delivery'")])  # doc(), P, UL, OL, CARD, ENTITY
R=REQ  # реквизиты из старой политики подставляются в REQ (см. ниже)
SITE='сайт <b>frito.kz</b> и мобильное приложение Frito (далее — Сервис)'
WA='<a href="{{ c.waUrl }}" target="_blank" rel="noopener">{{ c.phone }}</a>'
MAIL='<a href="{{ c.mailUrl }}">{{ c.email }}</a>'

